<section class="panel inset"><h2><?= h($card['title']) ?> — <?= h(PREP_STATES[$state]) ?></h2><p>Редакция <?= h($latest['revision']) ?> · шаблон v<?= h($template['revision']) ?> · SHA-256 доказательств <code><?= h($latest['evidence_hash']) ?></code></p><p>Редактор: <?= h($actors['editor'][$card['editor_id']]??'Полномочия отозваны') ?> · Юрист: <?= h($actors['lawyer'][$card['lawyer_id']]??'Полномочия отозваны') ?> · Уполномоченный: <?= h($actors['approver'][$card['approver_id']]??'Полномочия отозваны') ?></p>
<p><a href="<?= h(url('prep.print',['project'=>$selected,'id'=>$card['id'],'revision'=>$latest['revision']])) ?>">Печатная форма текста</a><?php if($latest['document_id']): ?> · <a href="<?= h(url('download',['id'=>$latest['document_id'],'v'=>$latest['document_revision']])) ?>">PDF на согласовании</a> · <code><?= h($latest['document_hash']) ?></code><?php else: ?> · PDF ещё не прикреплён<?php endif ?></p><pre class="prep-text"><?= h($latest['body']) ?></pre>
<?php if($writable&&$editor&&in_array($state,['draft','changes','approved'],true)): ?><details><summary>Создать новую редакцию</summary><form method="post"><?php $hidden('prep.revise') ?><label>Текст<textarea name="body" rows="16" maxlength="16000" required><?= h($latest['body']) ?></textarea></label><label>Конкретная версия PDF<select name="document"><option value="">Без PDF (черновик)</option><?php foreach($pdfs as $d): $pair=$d['id'].':'.$d['revision']; ?><option value="<?= h($pair) ?>"><?= h($d['title'].' v'.$d['revision']) ?></option><?php endforeach ?></select></label><p>Загрузите PDF через реестр документов. Сверьте его содержание с текстом. Новая редакция сбрасывает прежние согласования.</p><button>Сохранить редакцию</button></form></details><?php endif ?>
<?php $actions=[];if($writable&&$editor&&$state==='draft'&&$latest['document_id'])$actions['prep.submit']='Отправить юристу (PDF сверен с текстом)';if($writable&&$lawyer&&$state==='legal_review')$actions+=['prep.legal'=>'Согласовать юридически (PDF проверен)','prep.return'=>'Вернуть на исправление'];if($writable&&$approver&&$state==='approval')$actions+=['prep.approve'=>'Подтвердить документ (PDF проверен)','prep.return'=>'Вернуть на исправление'];if($user['role']==='owner'&&!in_array($state,['approved','cancelled'],true))$actions['prep.cancel']='Отменить';foreach($actions as $act=>$label): ?><form method="post" class="inset"><?php $hidden($act) ?><label>Основание / замечания<textarea name="note" required maxlength="2000" rows="2"></textarea></label><button><?= h($label) ?></button></form><?php endforeach ?>
<?php if($user['role']==='owner'&&!in_array($state,['approved','cancelled'],true)): ?><details><summary>Изменить маршрут (сброс согласований и PDF)</summary><form method="post"><?php $hidden('prep.assign') ?><?php foreach(['editor'=>'Редактор','lawyer'=>'Юрист','approver'=>'Уполномоченный'] as $role=>$label): ?><label><?= h($label) ?><select name="<?= h($role) ?>_id" required><?php selectOptions($actors[$role]??[],$card[$role.'_id']) ?></select></label><?php endforeach ?><label>Причина<textarea name="note" maxlength="2000" required></textarea></label><button>Назначить</button></form></details><?php endif ?></section>
<section class="panel inset"><h2>Редакции и сравнение</h2><?php foreach($history as $r): ?><p>v<?= h($r['revision']) ?> · <a href="<?= h(url('prep.print',['project'=>$selected,'id'=>$card['id'],'revision'=>$r['revision']])) ?>">Текст</a> · <a href="<?= h(url('preparation',['project'=>$selected,'id'=>$card['id'],'compare'=>$r['revision']])) ?>">Сравнить с текущей</a><?php if($r['document_id']): ?> · <a href="<?= h(url('download',['id'=>$r['document_id'],'v'=>$r['document_revision']])) ?>">PDF</a><?php endif ?></p><?php endforeach ?><?php if($diff!==null): ?><p>v<?= h($compare['revision']) ?> → v<?= h($latest['revision']) ?>. PDF: <?= h($compare['document_hash']??'нет') ?> → <?= h($latest['document_hash']??'нет') ?>. Сравнение текста, не извлечение текста PDF.</p><pre class="prep-text"><?php foreach($diff as [$sign,$line]): ?><span class="<?= $sign==='+'?'prep-add':($sign==='-'?'prep-del':'') ?>"><?= h($sign.' '.$line) ?></span><?= "\n" ?><?php endforeach ?></pre><?php endif ?></section>
